    acceptInvitation: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description The token from the invitation link. */
                token: components["parameters"]["InvitationToken"];
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["InvitationAccept"];
            };
        };
        responses: {
            /** @description The account is created and the person is signed in. */
            200: {
                headers: {
                    /** @description The session cookie, exactly as set by `POST /auth/login`. */
                    "Set-Cookie"?: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["CurrentUser"];
                };
            };
            404: components["responses"]["InvalidInvitation"];
            /** @description The organisation has no free seat. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "detail": "Seat limit reached."
                     *     }
                     */
                    "application/json": components["schemas"]["Error"];
                };
            };
            422: components["responses"]["ValidationFailed"];
            503: components["responses"]["ServiceUnavailable"];
        };
    };
