    getDemoProfilePdf: {
        parameters: {
            query?: {
                /** @description Language of the labels and of the disclaimer. English when absent. */
                lang?: "en" | "fr";
            };
            header?: never;
            path: {
                /** @description The resource's UUID. A value that is not a UUID answers 404, as an unknown id. */
                id: components["parameters"]["ResourceId"];
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description The PDF. */
            200: {
                headers: {
                    /** @description `attachment; filename="supplier-card-<name>-<date>.pdf"`, the name reduced to ASCII letters, digits and hyphens. */
                    "Content-Disposition"?: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/pdf": string;
                };
            };
            404: components["responses"]["NotFound"];
            422: components["responses"]["ValidationFailed"];
            /** @description The PDF cannot be made now, or too many PDFs are being made at once (the wait is short). `Retry-After` says when to try again. Nothing else in the demo is affected. */
            503: {
                headers: {
                    /** @description Seconds to wait before trying again. */
                    "Retry-After"?: number;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["Error"];
                };
            };
        };
    };
